"""Build all-order signed-volume diffusion states from historical moneyflow Parquet."""
from __future__ import annotations
import argparse,json
from pathlib import Path
import duckdb,numpy as np,pandas as pd
def rolling_pct(values):
 out=[]
 for i,value in enumerate(values):
  history=pd.Series(values[max(0,i-119):i+1]).dropna();out.append(float((history<=value).mean()) if pd.notna(value) and len(history)>=120 else np.nan)
 return out
def values(value):return list(value) if isinstance(value,(list,np.ndarray)) else []
def run(members_path,start,end,panel_path,focus_path):
 m=pd.read_csv(members_path,dtype=str);m["Symbol"]=m.ts_code.str[:6];m["in_date"]=pd.to_datetime(m.in_date,errors="coerce");m["out_date"]=pd.to_datetime(m.out_date,errors="coerce");m=m[["Symbol","name","l1_name","l2_name","in_date","out_date"]].drop_duplicates();con=duckdb.connect();con.register("members",m)
 sql="""with base as (select substr(ts_code,1,6) Symbol,strptime(cast(trade_date as varchar),'%Y%m%d')::date trade_date,(buy_sm_amount+buy_md_amount+buy_lg_amount+buy_elg_amount) all_buy,(sell_sm_amount+sell_md_amount+sell_lg_amount+sell_elg_amount) all_sell,(buy_lg_amount+buy_elg_amount) large_buy,(sell_lg_amount+sell_elg_amount) large_sell from read_parquet('overall/a-share-moneyflow-raw/moneyflow_*.parquet',union_by_name=true) where strptime(cast(trade_date as varchar),'%Y%m%d')::date between ? and ?),rates as (select *,all_buy+all_sell directional_amount,(large_buy-large_sell)/nullif(all_buy+all_sell,0) large_net_rate,case when trade_date<date '2022-01-01' then 'pre2022' else 'post2022' end method_epoch from base),thresholds as (select *,count(large_net_rate) over(partition by Symbol,method_epoch order by trade_date rows between 119 preceding and current row) obs,quantile_cont(large_net_rate,.9) over(partition by Symbol,method_epoch order by trade_date rows between 119 preceding and current row) q90,quantile_cont(large_net_rate,.1) over(partition by Symbol,method_epoch order by trade_date rows between 119 preceding and current row) q10 from rates),flags as (select *,obs>=120 and large_net_rate>0 and large_net_rate>=q90 buy_leader,obs>=120 and large_net_rate<0 and large_net_rate<=q10 sell_leader from thresholds),history_flags as (select *,sum(buy_leader::int) over(partition by Symbol order by trade_date rows between 2 preceding and current row)>=2 persistent_buy,sum(buy_leader::int) over(partition by Symbol order by trade_date rows between 5 preceding and 1 preceding)=0 new_buy from flags),joined as (select h.*,m.name,m.l1_name,m.l2_name from history_flags h join members m on m.Symbol=h.Symbol and h.trade_date>=m.in_date and (m.out_date is null or h.trade_date<=m.out_date) where lower(m.name) not like '%st%'),sector_rows as (select *,l1_name sector from joined union all select *, '半导体' sector from joined where l2_name='半导体'),lagged as (select *,lag(buy_leader) over(partition by sector,Symbol order by trade_date) previous_buy,greatest(large_buy-large_sell,0) positive_net,row_number() over(partition by sector,trade_date order by greatest(large_buy-large_sell,0) desc,Symbol) positive_rank from sector_rows),windowed as (select *,sum(positive_net) over(partition by sector,trade_date) positive_sum,sum(buy_leader::int) over(partition by sector,trade_date) buy_count_window from lagged) select trade_date,sector,count(*) eligible_count,sum(buy_leader::int) buy_count,sum(sell_leader::int) sell_count,sum(persistent_buy::int) persistent_buy_count,sum(new_buy::int) new_buy_count,sum(large_buy-large_sell)/nullif(sum(directional_amount),0) sector_large_net_rate,sum(case when positive_rank<=5 then positive_net else 0 end)/nullif(sum(positive_net),0) top5_positive_concentration,sum((buy_leader and coalesce(previous_buy,false))::int)/nullif(sum((buy_leader or coalesce(previous_buy,false))::int),0) buy_set_persistence,case when max(buy_count_window)>1 then -sum(case when positive_net>0 and positive_sum>0 then (positive_net/positive_sum)*ln(positive_net/positive_sum) else 0 end)/ln(max(buy_count_window)) else 0 end positive_net_entropy,list(Symbol order by large_net_rate desc) filter(where persistent_buy or new_buy) focus_symbols,list(large_net_rate order by large_net_rate desc) filter(where persistent_buy or new_buy) focus_rates from windowed group by trade_date,sector order by sector,trade_date"""
 try:panel=con.execute(sql,[start,end]).df()
 finally:con.close()
 panel["trade_date"]=pd.to_datetime(panel.trade_date);panel["buy_breadth"]=panel.buy_count/panel.eligible_count;panel["sell_breadth"]=panel.sell_count/panel.eligible_count;panel["new_buy_rate"]=panel.new_buy_count/panel.eligible_count;panel["focus_symbols_json"]=panel.focus_symbols.apply(lambda x:json.dumps(values(x)[:20],ensure_ascii=False));panel["focus_rates_json"]=panel.focus_rates.apply(lambda x:json.dumps([float(v) for v in values(x)[:20]]));focus_rows=[]
 name_map=dict(zip(m.Symbol,m.name))
 for row in panel.itertuples(index=False):
  for rank,(symbol,rate) in enumerate(zip(json.loads(row.focus_symbols_json),json.loads(row.focus_rates_json),strict=True),1):focus_rows.append({"trade_date":row.trade_date,"sector":row.sector,"rank":rank,"Symbol":symbol,"name":name_map.get(symbol),"large_net_rate":rate})
 panel["method_epoch"]=np.where(panel.trade_date<pd.Timestamp("2022-01-01"),"pre2022","post2022")
 for column in ["buy_breadth","sell_breadth","new_buy_rate","sector_large_net_rate","top5_positive_concentration","buy_set_persistence","positive_net_entropy"]:panel[column+"_pct120"]=panel.groupby(["sector","method_epoch"],group_keys=False)[column].transform(lambda s:pd.Series(rolling_pct(s.tolist()),index=s.index))
 panel=panel.drop(columns=["focus_symbols","focus_rates"]);panel.to_csv(panel_path,index=False,date_format="%Y-%m-%d");pd.DataFrame(focus_rows).to_csv(focus_path,index=False,date_format="%Y-%m-%d");return {"rows":len(panel),"focus_rows":len(focus_rows),"sectors":panel.sector.nunique(),"start":str(panel.trade_date.min().date()),"end":str(panel.trade_date.max().date()),"panel":panel_path,"focus":focus_path}
def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument("--members",default="overall/a-share-sw2021-members.csv");p.add_argument("--start",default="2018-01-01");p.add_argument("--end",default="2026-08-27");p.add_argument("--panel",default="overall/a-share-signed-volume-panel.csv");p.add_argument("--focus",default="overall/a-share-signed-volume-focus.csv");a=p.parse_args(argv);print(json.dumps(run(a.members,a.start,a.end,a.panel,a.focus),ensure_ascii=False,indent=2));return 0
if __name__=="__main__":raise SystemExit(main())
